// cspell:ignore Cpmn Ougr Tnsa Vith
// Upstream: ESLint v10.14.0 tests/lib/rules/no-invalid-regexp.js (73 valid, 39 invalid).
package no_invalid_regexp

import (
	"github.com/web-infra-dev/rslint/internal/plugins/typescript/rules/fixtures"
	"github.com/web-infra-dev/rslint/internal/rule_tester"
	"testing"
)

func TestNoInvalidRegexpUpstream(t *testing.T) {
	rule_tester.RunRuleTester(fixtures.GetRootDir(), "tsconfig.json", t, &NoInvalidRegexpRule, []rule_tester.ValidTestCase{
		{Code: "RegExp('')"},
		{Code: "RegExp()"},
		{Code: "RegExp('.', 'g')"},
		{Code: "new RegExp('.')"},
		{Code: "new RegExp"},
		{Code: "new RegExp('.', 'im')"},
		{Code: "global.RegExp('\\\\')"},
		{Code: "function foo(RegExp) { RegExp('['); }"},
		{Code: "function foo(RegExp) { new RegExp('['); }"},
		{Code: "let RegExp; RegExp('.', 'z');"},
		{Code: "RegExp('[', 'z');", Globals: map[string]any{"RegExp": "off"}},
		{Code: "new RegExp('.', y)"},
		{Code: "new RegExp('.', 'y')"},
		{Code: "new RegExp('.', 'u')"},
		{Code: "new RegExp('.', 'yu')"},
		{Code: "new RegExp('/', 'yu')"},
		{Code: "new RegExp('\\/', 'yu')"},
		{Code: "new RegExp('\\\\u{65}', 'u')"},
		{Code: "new RegExp('\\\\u{65}*', 'u')"},
		{Code: "new RegExp('[\\\\u{0}-\\\\u{1F}]', 'u')"},
		{Code: "new RegExp('.', 's')"},
		{Code: "new RegExp('(?<=a)b')"},
		{Code: "new RegExp('(?<!a)b')"},
		{Code: "new RegExp('(?<a>b)\\k<a>')"},
		{Code: "new RegExp('(?<a>b)\\k<a>', 'u')"},
		{Code: "new RegExp('\\\\p{Letter}', 'u')"},
		{Code: "RegExp('{', flags)"},
		{Code: "new RegExp('{', flags)"},
		{Code: "RegExp('\\\\u{0}*', flags)"},
		{Code: "new RegExp('\\\\u{0}*', flags)"},
		{Code: "RegExp('{', flags)", Options: []any{map[string]any{"allowConstructorFlags": []any{"u"}}}},
		{Code: "RegExp('\\\\u{0}*', flags)", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}},
		{Code: "new RegExp(pattern, 'g')"},
		{Code: "new RegExp('.' + '', 'g')"},
		{Code: "new RegExp(pattern, '')"},
		{Code: "new RegExp(pattern)"},
		{Code: "new RegExp('(?<\\\\ud835\\\\udc9c>.)', 'g')"},
		{Code: "new RegExp('(?<\\\\u{1d49c}>.)', 'g')"},
		{Code: "new RegExp('(?<𝒜>.)', 'g');"},
		{Code: "new RegExp('\\\\p{Script=Nandinagari}', 'u');"},
		{Code: "new RegExp('a+(?<Z>z)?', 'd')"},
		{Code: "new RegExp('\\\\p{Script=Cpmn}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Cypro_Minoan}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Old_Uyghur}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Ougr}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Tangsa}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Tnsa}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Toto}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Vith}', 'u')"},
		{Code: "new RegExp('\\\\p{Script=Vithkuqi}', 'u')"},
		{Code: "new RegExp('[A--B]', 'v')"},
		{Code: "new RegExp('[A&&B]', 'v')"},
		{Code: "new RegExp('[A--[0-9]]', 'v')"},
		{Code: "new RegExp('[\\\\p{Basic_Emoji}--\\\\q{a|bc|def}]', 'v')"},
		{Code: "new RegExp('[A--B]', flags)"},
		{Code: "new RegExp('[[]\\\\u{0}*', flags)"},
		{Code: "new RegExp('((?<k>a)|(?<k>b))')"},
		{Code: "new RegExp('(?ims:foo)')"},
		{Code: "new RegExp('(?ims-:foo)')"},
		{Code: "new RegExp('(?-ims:foo)')"},
		{Code: "new RegExp('(?s-i:foo)')"},
		{Code: "new RegExp('.', 'g')", Options: []any{map[string]any{"allowConstructorFlags": []any{}}}},
		{Code: "new RegExp('.', 'g')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}},
		{Code: "new RegExp('.', 'a')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}},
		{Code: "new RegExp('.', 'ag')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}},
		{Code: "new RegExp('.', 'ga')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}},
		{Code: "new RegExp(pattern, 'ga')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}},
		{Code: "new RegExp('.' + '', 'ga')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}},
		{Code: "new RegExp('.', 'a')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a", "z"}}}},
		{Code: "new RegExp('.', 'z')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a", "z"}}}},
		{Code: "new RegExp('.', 'az')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a", "z"}}}},
		{Code: "new RegExp('.', 'za')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a", "z"}}}},
		{Code: "new RegExp('.', 'agz')", Options: []any{map[string]any{"allowConstructorFlags": []any{"a", "z"}}}},
	}, []rule_tester.InvalidTestCase{
		{Code: "RegExp('[');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /[/: Unterminated character class.", Line: 1, Column: 1, EndLine: 1, EndColumn: 12}}},
		{Code: "RegExp('.', 'z');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'z'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 17}}},
		{Code: "RegExp('.', 'a');", Options: []any{map[string]any{}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'a'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 17}}},
		{Code: "new RegExp('.', 'a');", Options: []any{map[string]any{"allowConstructorFlags": []any{}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'a'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 21}}},
		{Code: "new RegExp('.', 'z');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'z'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 21}}},
		{Code: "RegExp('.', 'a');", Options: []any{map[string]any{"allowConstructorFlags": []any{"A"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'a'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 17}}},
		{Code: "RegExp('.', 'A');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'A'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 17}}},
		{Code: "new RegExp('.', 'az');", Options: []any{map[string]any{"allowConstructorFlags": []any{"z"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'a'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 22}}},
		{Code: "new RegExp('.', 'aa');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Duplicate flags ('a') supplied to RegExp constructor.", Line: 1, Column: 1, EndLine: 1, EndColumn: 22}}},
		{Code: "new RegExp('.', 'aA');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'A'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 22}}},
		{Code: "new RegExp('.', 'aaz');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a", "z"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Duplicate flags ('a') supplied to RegExp constructor.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp('.', 'azz');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a", "z"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Duplicate flags ('z') supplied to RegExp constructor.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp('.', 'aga');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Duplicate flags ('a') supplied to RegExp constructor.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp('.', 'uu');", Options: []any{map[string]any{"allowConstructorFlags": []any{"u"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Duplicate flags ('u') supplied to RegExp constructor.", Line: 1, Column: 1, EndLine: 1, EndColumn: 22}}},
		{Code: "new RegExp('.', 'ouo');", Options: []any{map[string]any{"allowConstructorFlags": []any{"u"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'oo'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp(')');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /)/: Unmatched ')'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 16}}},
		{Code: "new RegExp('\\\\a', 'u');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\a/u: Invalid escape.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp('\\\\a', 'u');", Options: []any{map[string]any{"allowConstructorFlags": []any{"u"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\a/u: Invalid escape.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "RegExp('\\\\u{0}*');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat.", Line: 1, Column: 1, EndLine: 1, EndColumn: 18}}},
		{Code: "new RegExp('\\\\u{0}*');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat.", Line: 1, Column: 1, EndLine: 1, EndColumn: 22}}},
		{Code: "new RegExp('\\\\u{0}*', '');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat.", Line: 1, Column: 1, EndLine: 1, EndColumn: 26}}},
		{Code: "new RegExp('\\\\u{0}*', 'a');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat.", Line: 1, Column: 1, EndLine: 1, EndColumn: 27}}},
		{Code: "RegExp('\\\\u{0}*');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat.", Line: 1, Column: 1, EndLine: 1, EndColumn: 18}}},
		{Code: "new RegExp('\\\\');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /\\/: \\ at end of pattern.", Line: 1, Column: 1, EndLine: 1, EndColumn: 17}}},
		{Code: "RegExp(')' + '', 'a');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'a'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 22}}},
		{Code: "new RegExp('.' + '', 'az');", Options: []any{map[string]any{"allowConstructorFlags": []any{"z"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'a'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 27}}},
		{Code: "new RegExp(pattern, 'az');", Options: []any{map[string]any{"allowConstructorFlags": []any{"a"}}}, Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid flags supplied to RegExp constructor 'z'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 26}}},
		{Code: "new RegExp('[[]', 'v');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /[[]/v: Unterminated character class.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp('.', 'uv');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Regex 'u' and 'v' flags cannot be used together.", Line: 1, Column: 1, EndLine: 1, EndColumn: 22}}},
		{Code: "new RegExp(pattern, 'uv');", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Regex 'u' and 'v' flags cannot be used together.", Line: 1, Column: 1, EndLine: 1, EndColumn: 26}}},
		{Code: "new RegExp('[A--B]' /* valid only with `v` flag */, 'u')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /[A--B]/u: Range out of order in character class.", Line: 1, Column: 1, EndLine: 1, EndColumn: 57}}},
		{Code: "new RegExp('[[]\\\\u{0}*' /* valid only with `u` flag */, 'v')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /[[]\\u{0}*/v: Unterminated character class.", Line: 1, Column: 1, EndLine: 1, EndColumn: 61}}},
		{Code: "new RegExp('(?<k>a)(?<k>b)')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /(?<k>a)(?<k>b)/: Duplicate capture group name.", Line: 1, Column: 1, EndLine: 1, EndColumn: 29}}},
		{Code: "new RegExp('(?ii:foo)')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /(?ii:foo)/: Duplicated flag 'i'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 24}}},
		{Code: "new RegExp('(?-ii:foo)')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /(?-ii:foo)/: Duplicated flag 'i'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 25}}},
		{Code: "new RegExp('(?i-i:foo)')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /(?i-i:foo)/: Duplicated flag 'i'.", Line: 1, Column: 1, EndLine: 1, EndColumn: 25}}},
		{Code: "new RegExp('(?-:foo)')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /(?-:foo)/: Invalid empty flags.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp('(?g:foo)')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /(?g:foo)/: Invalid group.", Line: 1, Column: 1, EndLine: 1, EndColumn: 23}}},
		{Code: "new RegExp('(?-u:foo)')", Errors: []rule_tester.InvalidTestCaseError{{MessageId: "regexMessage", Message: "Invalid regular expression: /(?-u:foo)/: Invalid group.", Line: 1, Column: 1, EndLine: 1, EndColumn: 24}}},
	})
}
